// No dotenv: all endpoints and disposable credentials are generated by the harness.
import { access } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
const cache = join(homedir(), ".cache/satchi-test-tools");
const env = {
  ...process.env,
  SATCHI_TEST_POSTGRES_BIN:
    process.env.SATCHI_TEST_POSTGRES_BIN ||
    join(cache, "pg17/opt/pgsql-17/bin"),
  SATCHI_TEST_POSTGREST:
    process.env.SATCHI_TEST_POSTGREST || join(cache, "postgrest14/postgrest"),
  SATCHI_TEST_AUTH_BIN:
    process.env.SATCHI_TEST_AUTH_BIN || join(cache, "auth2197/auth"),
};
if (process.argv.includes("--services")) {
  if (spawnSync("bwrap", ["--version"], { stdio: "ignore" }).status !== 0)
    throw new Error("Official service tests require Bubblewrap (bwrap)");
  env.SATCHI_TEST_OFFICIAL_SERVICES = "1";
  for (const name of ["storage", "edge", "realtime"]) {
    await access(join(cache, "services", name, "verified-image.json"));
  }
  await access(join(cache, "pg17/opt/pgsql-17/lib/wal2json.so"));
  console.log(
    "[test services] official Storage file backend + Edge user worker + Realtime; disposable native PostgreSQL/Auth/PostgREST",
  );
}
for (const file of [
  join(env.SATCHI_TEST_POSTGRES_BIN, "postgres"),
  env.SATCHI_TEST_POSTGREST,
  env.SATCHI_TEST_AUTH_BIN,
]) {
  try {
    await access(file);
  } catch {
    throw new Error(
      `Missing ${file}. Run python3 scripts/testing/setup-native-tools.py`,
    );
  }
}
if (process.argv.includes("--quick-match")) {
  env.SATCHI_TEST_QUICK_MATCH = "1";
  console.log(
    "[test flow] simultaneous Math Quick Match and two-browser Vocabulary matching",
  );
}
const selectedTests = process.argv.includes("--quick-match")
  ? [
      "tests/battle-quick-native.test.js",
      "tests/battle-matching-native.test.js",
    ]
  : [
      process.argv.includes("--realtime")
        ? "tests/supabase-realtime.test.js"
        : process.argv.includes("--critical")
          ? "tests/critical-pages-native.test.js"
          : process.argv.includes("--analytics")
            ? "tests/analytics-native.test.js"
            : process.argv.includes("--reading")
              ? "tests/battle-reading-vocabulary-native.test.js"
              : process.argv.includes("--battle-browser")
                ? "tests/battle-browser-native.test.js"
                : process.argv.includes("--battle-timer")
                  ? "tests/battle-timer-native.test.js"
                  : process.argv.includes("--battle-matching")
                    ? "tests/battle-matching-native.test.js"
                    : process.argv.includes("--battle-network")
                      ? "tests/battle-network-native.test.js"
                      : "tests/sprint-native.test.js",
    ];
const result = spawnSync(
  process.execPath,
  [
    "--test",
    "--test-concurrency=1",
    ...process.argv
      .slice(2)
      .filter((arg) => arg.startsWith("--test-name-pattern=")),
    ...selectedTests,
  ],
  { env, stdio: "inherit" },
);
process.exitCode = result.status ?? 1;
